export const BODY: string = "\n<p>كل وجهة تريد حجم صورة مختلفًا، والإعداد المسبق اختصار إلى الحجم الصحيح. بدل البحث عن أرقام منصة وكتابتها يدويًا، تنقر على إعداد مسبق فتُملأ الأبعاد.</p>\n<p>يربط هذا الدليل إعدادات مغير الحجم الجملي وأحجام التواصل الشائعة بالأماكن التي تتوقعها: خلاصات التواصل والمتاجر عبر الإنترنت والمدونات والصور المصغرة والشاشات والطباعة. ويشرح أيضًا متى لا ينطبق إعداد مسبق.</p>\n<p>الإعدادات المسبقة توفر الوقت، لكنها لا تحل محل الحكم. الإعداد المسبق يعطيك الإطار؛ وصورك واستراتيجيتك وضبط الجودة تقرر ما يحتويه الإطار. اقرأ الدليل ثم افتح <a href=\"/ar/taghyir-hajm-jumli-lis-suwar/\">مغير حجم الصور الجملي</a>.</p>\n<h2 id=\"what-presets-are\">ما هي الإعدادات المسبقة</h2>\n<p>الإعداد المسبق حجم محفوظ: زوج عرض وارتفاع يطابق وجهة شائعة. عند النقر عليه، يملأ حقول البكسل، فلا شيء لكتبه ولا شيء لكتبه خطأ.</p>\n<p>يأتي مغير الحجم الجملي بأربعة إعدادات سريعة: Full HD 1920 بكسل ومدونة 1200 بكسل وتجارة إلكترونية 1000 في 1000 وصورة مصغرة 600 بكسل. والإعدادات نقاط بداية لا اختيارات مغلقة: إذا طلب متجر 1200 في 1200 بدل 1000 في 1000، انقر إعداد التجارة الإلكترونية وغيّر الحقول.</p>\n<h2 id=\"social-presets\">إعدادات التواصل الاجتماعي: الخلاصات والقصص والترويسات</h2>\n<p>منصات التواصل هي الوجهات الأشد في حجم الصورة، لأنها تقص بشكل لا يمكن التنبؤ به عندما تصل صورة خاطئة.</p>\n<p>منشور مربع 1080 في 1080 يملأ الخلاصة بشكل نظيف، بينما قصة 1080 في 1920 تملأ شاشة الهاتف دون أشرطة سوداء. واكتب هذه الأحجام في مغير الحجم الجملي مباشرة. وصور يوتيوب المصغرة تريد 1280 في 720، وأغلفة فيسبوك تريد 851 في 315، وترويسات إكس تريد 1500 في 500.</p>\n<h2 id=\"ecommerce-presets\">إعدادات التجارة الإلكترونية: صورة المنتج المربعة</h2>\n<p>المتاجر عبر الإنترنت تريد الاتساق فوق كل شيء. شبكة بطاقات حيث كل بلاطة 1000 في 1000 تبدو احترافية، بينما شبكة بأحجام متنوعة تبدو فوضوية.</p>\n<p>استخدم أبعادًا دقيقة 1000 في 1000 مع التغطية لشبكة منتجات. كل بلاطة تصبح متطابقة وممتلئة من حافة إلى حافة، وتبقى الشبكة محاذاة تمامًا. ولصورة منتج واحدة في صفحتها الخاصة، الملاءمة القصوى 1000 في 1000 أو 1200 في 1200 أفضل غالبًا.</p>\n<h2 id=\"blog-and-web-presets\">إعدادات المدونة والويب: عمود 1200 بكسل</h2>\n<p>صور محتوى المدونة تعيش في عمود بعرض ثابت، عادة نحو 1200 بكسل، وإعداد المدونة مصنوع لهذا العمود. استخدم الملاءمة القصوى 1200 في 1200 أو العرض الموحد 1200 بكسل.</p>\n<p>العرض الموحد يناسب عمود المدونة أكثر، لأنه يضمن العرض المشترك الذي يجعل العمود مستقيمًا. والملاءمة القصوى تناسب مدونة بتصاميم متنوعة، حيث بعض الصور عريضة وبعضها طويل. ومجلدات المدونة تخلط لقطات الشاشة والصور والرسوم غالبًا، فأبقِ صيغة الإخراج أصلية أو حوّل الدفعة كلها إلى WebP.</p>\n<h2 id=\"thumbnail-presets\">إعدادات الصور المصغرة: صور صغيرة يجب أن تُقرأ</h2>\n<p>الصور المصغرة صور صغيرة ما زالت يجب أن توصل رسالة، وإعداد الصورة المصغرة يثبت 600 في 600 لهذا العمل. قوائم المنتجات ونتائج البحث وشبكات المعارض كلها تعتمد على بلاطات صغيرة متطابقة.</p>\n<p>التفاصيل الدقيقة تختفي عند 600 بكسل، فيجب أن يكون الموضوع كبيرًا ومتمركزًا وعالي التباين في الإطار. منظر عريض مصغّر إلى مربع 600 يتحول إلى شريط رفيع من التفاصيل. واستخدم الدقيق مع التغطية لشبكات الصور المصغرة، فتكون كل بلاطة ممتلئة ومتطابقة.</p>\n<h2 id=\"full-hd-presets\">Full HD: حجم الشاشة العريضة</h2>\n<p>Full HD 1920 في 1080 هو حجم الشاشة العريضة القياسي، والإعداد المسبق يملؤه بلمسة واحدة. يناسب الصور الرئيسية وإطارات الفيديو وشرائح العروض وأي شيء يُعرض على شاشة عريضة.</p>\n<p>صورة بعرض 1920 أكبر مما تحتاجه صورة مدونة، فلا تستخدم Full HD لصور محتوى داخل مقال. البكسلات الزائدة تبطئ الصفحة دون فائدة مرئية، لأن فجوة العرض تقيس 1200 بكسل عرضًا فقط. وطابق الإعداد المسبق مع الفجوة لا مع أكبر حجم متاح.</p>\n<h2 id=\"print-sizes\">أحجام الطباعة: عندما لا تنطبق الإعدادات المسبقة</h2>\n<p>الطباعة ليس لها إعدادات مسبقة في مغير الحجم الجملي، لأن أحجام الطباعة تُحدد بالبوصات والنقاط في البوصة، لا باتفاقيات الشاشة.</p>\n<p>طباعة 6 في 4 بوصات بـ300 نقطة في البوصة تحتاج 1800 في 1200 بكسل، والطباعة الأكبر تحتاج أكثر بنسبة. واكتب هذه الأرقام في حقول البكسل يدويًا. وأبقِ الجودة بين 95 بالمئة و100 بالمئة لدفعات الطباعة، وفضّل PNG أو JPG عالي الجودة كمخرجات.</p>\n<h2 id=\"custom-sizes\">الأحجام المخصصة: متى تكتب الأرقام</h2>\n<p>الإعدادات المسبقة تغطي الحالات الشائعة، لكن كثيرًا من الوجهات تنشر أحجامها الدقيقة الخاصة. متجر قد يطلب 1200 في 1200، ونشرة قد تريد عرض 600 بكسل، وعميل قد يطلب شيئًا آخر تمامًا.</p>\n<p>اكتب حجمًا مخصصًا عندما تعطيك الوجهة رقمًا دقيقًا. التخمين بأقرب إعداد مسبق قد يسبب رفضًا أو قصًا محرجًا عند الرفع، بينما كتابة الحجم المنشور تعمل في المرة الأولى. والأحجام المخصصة تناسب أيضًا الأشكال غير المعتادة مثل اللافتة البانورامية والإنفوغرافيك الطويل والصورة الرمزية المربعة.</p>\n<h2 id=\"mixed-orientations-and-presets\">الاتجاهات المختلطة والإعدادات المسبقة</h2>\n<p>الإعدادات المسبقة تثبت حجمًا، لكنها لا تحل مشكلة الشكل في دفعة متنوعة. إعداد 1000 في 1000 مطبق على مجلد مناظر وبورتريه ينتج نتائج مختلفة حسب الاستراتيجية.</p>\n<p>الملاءمة القصوى مع إعداد مربع هي التركيبة الآمنة لمجلد متنوع. كل صورة تناسب داخل صندوق 1000 في 1000 وتحافظ على شكلها ولا يُقص شيء. أما الدقيق مع التغطية والإعداد المربع فهو التركيبة الصارمة للشبكة: كل صورة تصبح 1000 في 1000 تمامًا، ممتلئة من حافة إلى حافة، مع قص الزائد.</p>\n<h2 id=\"quality-and-format-per-preset\">الجودة والصيغة لكل إعداد مسبق</h2>\n<p>لكل إعداد مسبق جودة وصيغة طبيعية تترافق معه. الإعدادات الاجتماعية والويب تناسب WebP أو JPG بجودة قريبة من 85 بالمئة، ما يبقي الملفات خفيفة للتحميل السريع.</p>\n<p>إعدادات التجارة الإلكترونية تناسب JPG بجودة 85 بالمئة، مع ألوان وفية وحواف حادة. وإعدادات الصور المصغرة يمكنها استخدام جودة أقل قليلًا، قرب 80 بالمئة، لأن التفاصيل الدقيقة غير مرئية عند 600 بكسل. أما أحجام الطباعة فتحتاج المعاملة المعاكسة: جودة 95 إلى 100 بالمئة وإخراج PNG أو JPG عالي الجودة.</p>\n<h2 id=\"when-not-to-use-a-preset\">متى لا تستخدم إعدادًا مسبقًا</h2>\n<p>لا تستخدم إعدادًا مسبقًا عندما تعطيك الوجهة حجمًا دقيقًا مختلفًا عنه. الإعداد القريب يبقى خاطئًا إذا رفضت المنصة الصورة أو قصتها بشكل سيئ. اكتب الحجم المنشور بدلًا من ذلك.</p>\n<p>ولا تستخدم إعدادًا مربعًا لدفعة صور عريضة يجب أن تبقى عريضة. إجبار صورة عريضة على إطار مربع بالدقيق والتغطية يتخلص من ثلث الصورة. ولا تستخدم إعداد Full HD لصور ستُعرض صغيرة، فصورة 1920 بكسل في فجوة 600 بكسل تهدر النطاق الترددي وتبطئ الصفحة دون فائدة مرئية.</p>\n<h2 id=\"preset-mistakes\">أخطاء الإعدادات المسبقة التي يجب تجنبها</h2>\n<p>خطأ الإعدادات الأكثر شيوعًا هو تطبيق إعداد واحد على كل الوجهات. صورة واحدة مغير حجمها إلى 1080 في 1080 لا يمكن أن تخدم منشورًا مربعًا وقصة طويلة وغلافًا عريضًا في الوقت نفسه.</p>\n<p>الخطأ الثاني هو نسيان أن الإعدادات تثبت الأبعاد لا الجودة. صورة منتج 1000 في 1000 محفوظة كـPNG تبقى ثقيلة، وصورة مدونة 1200 بكسل محفوظة بجودة منخفضة تبدو ناعمة. والخطأ الثالث هو استخدام إعداد بديل عن مراجعة النتيجة.</p>\n<h2 id=\"preset-cheat-sheet\">ورقة مرجع الإعدادات المسبقة</h2>\n<p>احفظ هذه القائمة قرب مساحة عملك. تغطي الأحجام التي يوصي بها هذا الدليل لكل وجهة، والاستراتيجية التي ترافق كلًا منها.</p>\n<p>للخطوات العملية للدفعة، اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-suwar-mutaaddida/\">كيف تغيّر حجم صور متعددة دفعة واحدة</a>، وللدليل الكامل للأداة اقرأ <a href=\"/ar/blog/dalil-taghyir-hajm-as-suwar-al-jumli/\">مغير حجم الصور الجملي: الدليل الكامل</a>. ولصورة واحدة، استخدم <a href=\"/ar/taghyir-hajm-as-suwar/\">مغير حجم الصور</a> أو اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-as-sura/\">كيف تغيّر حجم صورة عبر الإنترنت</a>.</p>\n<ul>\n<li>منشور إنستغرام: 1080 في 1080، دقيق مع تغطية لبلاطة مربعة ممتلئة في الخلاصة.</li>\n<li>قصة إنستغرام: 1080 في 1920، ملاءمة قصوى فلا يُفقد شيء في الإطار الطويل.</li>\n<li>صورة يوتيوب المصغرة: 1280 في 720، ملاءمة قصوى لصورة مصغرة عريضة تُقرأ صغيرة.</li>\n<li>غلاف فيسبوك: 851 في 315، دقيق مع تغطية لإطار الترويسة العريض.</li>\n<li>ترويسة إكس: 1500 في 500، دقيق مع تغطية لإطار لافتة عريض جدًا.</li>\n<li>منتج تجارة إلكترونية: 1000 في 1000، دقيق مع تغطية لشبكة موحدة.</li>\n<li>محتوى مدونة: عرض 1200، عرض موحد أو ملاءمة قصوى لعمود مرتب.</li>\n<li>صورة مصغرة: 600 في 600، دقيق مع تغطية لبلاطات صغيرة متطابقة.</li>\n<li>صورة رئيسية Full HD: 1920 في 1080، ملاءمة قصوى لصورة شاشة عريضة حادة.</li>\n<li>طباعة 6 في 4 بوصات: 1800 في 1200 بـ300 نقطة في البوصة، تُكتب يدويًا.</li>\n</ul>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي إعداد مسبق أستخدم لبطاقة منتج؟","answer":"استخدم إعداد التجارة الإلكترونية 1000 في 1000 بأبعاد دقيقة وتغطية، فتكون كل بلاطة في شبكة البطاقة متطابقة وممتلئة من حافة إلى حافة. هذا الاتساق يجعل المتجر يبدو احترافيًا."},{"question":"هل يمكنني استخدام إعداد اجتماعي لدفعة كاملة دفعة واحدة؟","answer":"نعم، اكتب الحجم الاجتماعي، مثل 1080 في 1080 لمنشور مربع، في حقول البكسل وشغّل الدفعة. إعدادات مغير الحجم الجملي تغطي أحجام الويب والمتاجر، لكن الحقول تقبل أي حجم من 1 إلى 12000 بكسل."},{"question":"أي إعداد مسبق أفضل لصور المدونة؟","answer":"إعداد المدونة 1200 بكسل، باستخدام الملاءمة القصوى أو العرض الموحد، هو أفضل افتراضي لصور محتوى المدونة. يجعل كل صورة بعرض 1200 بكسل بينما تحافظ كل منها على شكلها."},{"question":"هل يجب أن تستخدم الصور المصغرة نفس إعداد الصور الكاملة؟","answer":"لا، الصور المصغرة تحتاج حجمها الخاص، عادة 600 في 600 بأبعاد دقيقة وتغطية، فتكون كل بلاطة في قائمة أو شبكة متطابقة. صورة كاملة مغير حجمها إلى 1200 بكسل كبيرة جدًا وثقيلة لبلاطة مصغرة."},{"question":"هل تغيّر الإعدادات المسبقة جودة الصورة أو صيغتها؟","answer":"لا، الإعداد المسبق يملأ حقلي العرض والارتفاع فقط؛ لا يمس الصيغة ولا الجودة. ما زلت تحتاج إلى اختيار صيغة الإخراج وشريط الجودة بنفسك. ولإعدادات الويب، WebP أو JPG بجودة قرب 85 بالمئة خيار جيد."},{"question":"أي حجم أستخدم لصورة مطبوعة؟","answer":"أحجام الطباعة تُكتب يدويًا لا تُختار من إعداد مسبق. طباعة 6 في 4 بوصات بـ300 نقطة في البوصة تحتاج 1800 في 1200 بكسل، والطباعة الأكبر تحتاج أكثر بنسبة. واستخدم جودة 95 إلى 100 بالمئة للطباعة."}];
